/* 구슬 레이스 — 진행
 *
 * 이건 실력 게임이 아니라 **여럿이서 뭔가를 정할 때 쓰는 도구**다. 그래서 설계의 1급 목표가
 * 재미가 아니라 **공정성과 그 증명**이다:
 *   · 구슬은 전부 동일하다 (반지름·질량·반발계수·마찰). 다른 건 색과 번호뿐
 *   · 맵은 매 판 고정이고 좌우 대칭이다
 *   · 출발 자리는 매 판 무작위로 섞어 배정한다  ← 참가자별 확률이 같아지는 지점은 여기다
 *   · 결과를 미리 정해놓고 애니메이션만 재생하지 않는다. 시드를 화면에 띄우고
 *     "같은 시드로 다시" 로 재현할 수 있게 해 그걸 증명한다
 *
 * 앱 안에 돈·포인트·베팅 금액은 없고, 그런 낱말도 쓰지 않는다.
 */
(function (global) {
  'use strict';

  var C = Courses;

  var COLORS = [
    '#FF5D5D', '#FF9A3C', '#FFD84D', '#8BE04E', '#34C77B', '#35D0C0',
    '#4DA6FF', '#6C7BFF', '#A97BFF', '#FF6FD8', '#D0A03C', '#AEB7D4'
  ];

  var MODES = [
    { key: 'last', name: '꼴찌 뽑기', sub: '커피 사는 사람 정하기', verb: '뽑힌 사람' },
    { key: 'first', name: '1등 뽑기', sub: '한 명만 고르기', verb: '뽑힌 사람' },
    { key: 'rank', name: '등수 지정', sub: '원하는 등수로', verb: '지목된 사람' },
    { key: 'order', name: '순서 정하기', sub: '도착 순서 그대로', verb: '순서' }
  ];

  var MIN_P = 2, MAX_P = 12, MAX_MARBLES = 20;

  var S = null;
  // Presentation bounds use wall time; never consume the physics RNG.
  var CONTEST = { zone: 760, spreadY: 260, spreadX: 360, duration: 2.4, cooldown: 1.8, speed: 0.42 };

  function modeByKey(k) {
    for (var i = 0; i < MODES.length; i++) if (MODES[i].key === k) return MODES[i];
    return MODES[0];
  }

  /**
   * @param opt { entries:[{name,count}], modeKey, rank, courseKey, seed }
   */
  function start(opt) {
    var entries = opt.entries.slice(0, MAX_P);
    var seed = opt.seed >>> 0;
    var rng = Rng.make(seed);
    var course = C.byKey(opt.courseKey);

    // 사람 → 구슬. 여러 개를 건 사람은 그만큼 걸릴(뽑힐) 확률이 올라간다
    var marbles = [], total = 0, i, k;
    for (i = 0; i < entries.length && total < MAX_MARBLES; i++) {
      var cnt = Math.max(1, Math.min(9, entries[i].count | 0 || 1));
      for (k = 0; k < cnt && total < MAX_MARBLES; k++) {
        marbles.push({
          id: total, owner: i, num: i + 1, name: entries[i].name,
          color: COLORS[i % COLORS.length], dup: cnt > 1 ? (k + 1) : 0,
          x: 0, y: 0, vx: 0, vy: 0, a: 0, w: 0, r: C.R,
          held: true, done: false, rank: 0, slowT: 0, stallT: 0, best: -1e9, trail: []
        });
        total++;
      }
    }

    /* 출발 자리 배정. **한 통에 모아 담는다** — 화면 폭 전체에 한 줄로 세우면
       코스가 섞을 일이 없어 출발 자리가 그대로 순위가 된다.
       배정 자체도 시드로 섞지만, 애초에 자리 차이가 거의 없게 만드는 게 먼저다. */
    var slots = [];
    var perRow = Math.min(total, 5);
    var rows = Math.ceil(total / perRow);
    for (var r = 0; r < rows; r++) {
      var inRow = Math.min(perRow, total - r * perRow);
      for (k = 0; k < inRow; k++) {
        slots.push({ x: C.MID + (k - (inRow - 1) / 2) * 52, y: C.START_Y - r * 50 });
      }
    }
    rng.shuffle(slots);
    for (i = 0; i < marbles.length; i++) {
      marbles[i].x = slots[i].x + rng.range(-4, 4);
      marbles[i].y = slots[i].y - rng.range(0, 8);
      marbles[i].slot = i;
    }

    var world = new Physics.World({
      gravity: course.gravity, restitution: course.restitution,
      friction: course.friction, drag: course.drag,
      left: C.LEFT, right: C.RIGHT,
      pegs: course.pegs, walls: course.walls,
      rotors: course.rotors, seesaws: course.seesaws,
      marbles: marbles
    });

    var mode = modeByKey(opt.modeKey);
    S = {
      seed: seed, rng: rng, course: course, mode: mode,
      // 등수는 **모드가 정한다.** opt.rank 는 '몇 등 지정' 일 때만 쓴다 —
      // 그러지 않으면 '꼴찌가 걸린다' 인데 1등이 걸리는 사고가 난다 (실측)
      wantRank: mode.key === 'first' ? 1
        : mode.key === 'rank' ? Math.max(1, Math.min(total, opt.rank | 0 || 1))
        : total,
      entries: entries, n: total, people: entries.length,
      world: world, marbles: marbles,
      cam: new Camera(course),
      phase: 'ready',            // ready → racing → done
      phaseT: 1.6,
      raceT: 0,
      order: [],
      picked: null,
      leadY: C.START_Y,
      hits: [],
      slow: 1, manualSlow: false, decisive: null,
      autoSlowT: 0, slowCooldown: 0, contestLatch: false, selectedOwner: null,
      aim: { x: C.MID + 54, y: C.START_Y + 460, z: 1 }
    };
    return S;
  }

  function state() { return S; }

  /** 구슬이 어딘가에 끼면 판이 안 끝난다. 흔드는 값도 시드에서 뽑아 재현성을 지킨다 */
  /* 흔드는 값도 시드에서 뽑아 재현성을 지킨다.
     **아래로 치우쳐 민다** — 위로 밀면 좁은 통로에 들어간 구슬을 도로 뱉어내
     구제 장치가 오히려 판을 못 끝내게 만든다 (통과 시험 34/34 → 32/34 로 악화) */
  function unstick(m) {
    m.vx += S.rng.range(-230, 230);
    m.vy += S.rng.range(-30, 240);
    m.w += S.rng.range(-14, 14);
    m.slowT = 0;
  }

  function onStep(w) {
    var i, m, lead = -1e9;
    for (i = 0; i < S.marbles.length; i++) {
      m = S.marbles[i];
      if (m.done) continue;
      if (m.y > lead) lead = m.y;
      if (m.y - m.r > S.course.finishY) {
        m.done = true;
        m.rank = S.order.length + 1;
        S.order.push(m);
        continue;
      }
      var sp = Math.abs(m.vx) + Math.abs(m.vy);
      if (sp < 52) {
        m.slowT += Physics.DT;
        if (m.slowT > 0.8) unstick(m);
      } else if (m.slowT > 0) {
        m.slowT = Math.max(0, m.slowT - Physics.DT * 2);
      }
      // 빠르게 움직이는데 **앞으로 못 나가는** 경우 — 벨트나 회전체를 도는 중이다.
      // 속도만 보면 못 잡는다
      if (m.y > m.best + 26) { m.best = m.y; m.stallT = 0; }
      else {
        m.stallT = (m.stallT || 0) + Physics.DT;
        if (m.stallT > 3.2) { unstick(m); m.vy += 260; m.stallT = 0; }
      }
    }
    // A single remaining PHYSICAL marble has a known last rank, wherever it is.
    // Both frame advance and fastForward call this same fixed-step callback.
    var remaining = S.marbles.filter(function (q) { return !q.done; });
    if (remaining.length === 1 && S.order.length === S.n - 1) {
      m = remaining[0]; m.done = true; m.rank = S.n; S.order.push(m);
    }
    if (lead > -1e8) S.leadY = lead;
    // 오래 걸리면 중력을 함께 올린다 — 모든 구슬에 똑같이 걸리므로 순위를 건드리지 않는다
    if (w.t > 55) w.gBoost = Math.min(3.0, 1 + (w.t - 55) * 0.15);
  }

  /** Shared camera/name attention: trailing danger vs the target rank boundary. */
  function attention() {
    if (!S) return [];
    var live = S.marbles.filter(function (m) { return !m.done; });
    live.sort(function (a, b) { return b.y - a.y || a.id - b.id; });
    if (S.mode.key === 'last' || S.mode.key === 'order') return live.slice(-3);
    if (S.mode.key === 'first') return live.slice(0, 3);
    var boundary = S.wantRank - S.order.length - 1;
    return live.slice(Math.max(0, boundary - 1), Math.max(0, boundary - 1) + 3);
  }

  function cameraAim() {
    var live = attention();
    if (!live.length) return { x: C.MID + 54, y: S.course.finishY - 260, z: 1.5 };
    var loY = 1e9, hiY = -1e9, loX = 1e9, hiX = -1e9;
    live.forEach(function (m) {
      loY = Math.min(loY, m.y); hiY = Math.max(hiY, m.y);
      loX = Math.min(loX, m.x); hiX = Math.max(hiX, m.x);
    });
    var z = Math.min(Camera.VH / (hiY - loY + Camera.MARGIN), Camera.VW / (hiX - loX + Camera.MARGIN));
    z = Math.max(0.86, Math.min(1.65, z));
    return { x: (loX + hiX) / 2, y: (hiY + loY) / 2 + 90 / z, z: z };
  }

  function contestGroup() {
    var live = S.marbles.filter(function (m) { return !m.done; });
    if (live.length < 2) return [];
    if (S.mode.key === 'last' || S.mode.key === 'order') {
      if (live.length > 3) return [];
    } else {
      // Show the next target boundary only while that rank is still undecided.
      if (S.order.length >= S.wantRank || S.wantRank - S.order.length > 3) return [];
      live = attention();
    }
    var entry = S.course.entryY, group = live.filter(function (m) {
      return m.y >= entry - CONTEST.zone && m.y <= entry + m.r;
    });
    if (group.length < 2) return [];
    var ys = group.map(function (m) { return m.y; }), xs = group.map(function (m) { return m.x; });
    if (Math.max.apply(null, ys) - Math.min.apply(null, ys) > CONTEST.spreadY ||
        Math.max.apply(null, xs) - Math.min.apply(null, xs) > CONTEST.spreadX) return [];
    return group;
  }

  function presentation(dt) {
    var group = contestGroup();
    S.slowCooldown = Math.max(0, S.slowCooldown - dt);
    if (!group.length) { S.contestLatch = false; S.autoSlowT = 0; }
    else if (!S.contestLatch && S.slowCooldown === 0) {
      S.contestLatch = true; S.autoSlowT = CONTEST.duration;
    }
    if (S.autoSlowT > 0) {
      S.autoSlowT = Math.max(0, S.autoSlowT - dt);
      if (S.autoSlowT === 0) S.slowCooldown = CONTEST.cooldown;
    }
    S.decisive = S.autoSlowT > 0 ? group[0] : null;
    return S.manualSlow ? 0.34 : !S.reducedMotion && S.autoSlowT > 0 ? CONTEST.speed : 1;
  }

  function selectOwner(owner) {
    if (!S) return;
    S.selectedOwner = owner == null || S.selectedOwner === owner ? null : owner;
  }

  /** Actual viewport (no drawing overscan). Prefer any visible marble of the owner. */
  function selectionGuide() {
    if (!S || S.selectedOwner == null) return '';
    var selected = S.marbles.filter(function (m) { return !m.done && m.owner === S.selectedOwner; });
    var name = S.entries[S.selectedOwner].name;
    if (!selected.length) return name + ' · 도착했습니다';
    var cam = S.cam, halfW = Camera.VW / (2 * cam.z), halfH = Camera.VH / (2 * cam.z);
    function visible(m) { return Math.abs(m.x - cam.x) <= halfW && Math.abs(m.y - cam.y) <= halfH; }
    if (selected.some(visible)) return name + ' · 화면 안에서 강조 중';
    var m = selected[0], directions = [];
    if (m.y < cam.y - halfH) directions.push('↑ 화면 위');
    if (m.y > cam.y + halfH) directions.push('↓ 화면 아래');
    if (m.x < cam.x - halfW) directions.push('← 화면 왼쪽');
    if (m.x > cam.x + halfW) directions.push('→ 화면 오른쪽');
    return name + ' ' + directions.join(' · ') + ' · 미니맵에서 위치 확인';
  }

  function resultText() {
    if (!S || S.phase !== 'done') return '';
    return S.course.name + ' · ' + S.mode.name + '\n' +
      S.order.map(function (m) { return m.rank + '등 ' + m.name + (m.dup ? ' (' + m.dup + ')' : ''); }).join('\n') +
      '\n다시 보기 코드 ' + Rng.label(S.seed);
  }

  function step(dt) {
    if (!S) return;
    if (S.phase === 'ready') {
      S.phaseT -= dt;
      S.aim = { x: C.MID + 54, y: C.START_Y + 420, z: 1.05 };
      S.cam.follow(S.aim, dt);
      if (S.phaseT <= 0) {
        S.phase = 'racing';
        for (var i = 0; i < S.marbles.length; i++) S.marbles[i].held = false;
        Sound.gate();
      }
      return;
    }
    if (S.phase !== 'racing') { S.aim = cameraAim(); S.cam.follow(S.aim, dt); return; }

    S.raceT += dt;
    var want = presentation(dt);
    // 배속은 부드럽게 갈아탄다 — 뚝 끊기면 연출이 아니라 렉으로 보인다
    S.slow += (want - S.slow) * Math.min(1, dt * 7);
    S.world.hits.length = 0;
    var before = S.order.length;
    S.world.advance(dt * S.slow, onStep);
    S.hits = S.world.hits;

    for (var k = 0; k < S.hits.length; k++) {
      var h = S.hits[k];
      Sound.clack(h.y - S.cam.y + 720, h.speed, h.kind);
      FX.spark(h.x, h.y, h.speed, h.kind === 'bump' ? '#FFD84D' : null);
    }
    for (k = before; k < S.order.length; k++) {
      var m = S.order[k];
      Sound.arrive(m.rank, S.n);
      FX.ring(m.x, S.course.finishY, m.color);
      if (m.rank === S.wantRank && S.mode.key !== 'order') FX.burst(m.x, S.course.finishY, m.color, 26);
    }

    // 궤적 — 어느 구슬이 어디서 왔는지 눈으로 따라갈 수 있게
    for (k = 0; k < S.marbles.length; k++) {
      m = S.marbles[k];
      if (m.done) continue;
      m.trail.push(m.x, m.y);
      if (m.trail.length > 16) m.trail.splice(0, 2);
    }

    S.aim = cameraAim();
    S.cam.follow(S.aim, dt);
    if (S.order.length >= S.n) finish();
  }

  function finish() {
    S.phase = 'done';
    if (S.mode.key === 'order') S.picked = null;
    else S.picked = S.order[Math.max(0, Math.min(S.order.length - 1, S.wantRank - 1))] || null;
    Sound.result(S.mode.key);
    FX.flash('#FFE9A0', 0.26);
    FX.shake(9, 0.4);
  }

  /** 결과를 기다리지 않고 넘기기 — 물리를 건너뛰는 게 아니라 빨리 감는다 */
  function fastForward(seconds) {
    if (!S || (S.phase !== 'racing' && S.phase !== 'ready')) return 0;
    if (S.phase === 'ready') {
      S.phase = 'racing';
      for (var i = 0; i < S.marbles.length; i++) S.marbles[i].held = false;
    }
    var n = 0, budget = Math.min(seconds, 240) / Physics.DT;
    while (S.order.length < S.n && n < budget) {
      S.world.step();
      onStep(S.world);
      n++;
    }
    if (S.order.length >= S.n) finish();
    return n;
  }

  /** 화면 연출만 바꾼다 — 물리에는 손대지 않으므로 결과와 무관하다 */
  function toggleSlow() {
    if (!S) return false;
    S.manualSlow = !S.manualSlow;
    return S.manualSlow;
  }

  global.Game = {
    COLORS: COLORS, MODES: MODES, MIN_P: MIN_P, MAX_P: MAX_P, MAX_MARBLES: MAX_MARBLES,
    start: start, state: state, step: step, modeByKey: modeByKey,
    fastForward: fastForward, toggleSlow: toggleSlow, cameraAim: cameraAim,
    attention: attention, selectOwner: selectOwner, selectionGuide: selectionGuide, resultText: resultText, CONTEST: CONTEST
  };
})(window);
